//! 🧊️ First-party bounded closed-solid subtraction in source coordinates.
use std::collections::{BTreeMap,BTreeSet,HashMap,HashSet};
pub type SolidPoint=[f64;3];
#[derive(Clone,Debug,Default,PartialEq)]
pub struct SolidMesh{pub vertices:Vec<SolidPoint>,pub triangles:Vec<[u32;3]>}
#[derive(Clone,Copy,Debug)]
pub struct SolidBooleanLimits{pub work:usize,pub polygons:usize,pub depth:usize}
impl Default for SolidBooleanLimits{fn default()->Self{Self{work:2_000_000,polygons:200_000,depth:256}}}
type Result<T>=std::result::Result<T,String>;
type Point=SolidPoint;
const EPS:f64=1e-9;
fn fail<T>(reason:&str)->Result<T>{Err(format!("boolean-{reason}"))}
fn add(a:Point,b:Point)->Point{[a[0]+b[0],a[1]+b[1],a[2]+b[2]]}
fn sub(a:Point,b:Point)->Point{[a[0]-b[0],a[1]-b[1],a[2]-b[2]]}
fn mul(a:Point,k:f64)->Point{[a[0]*k,a[1]*k,a[2]*k]}
fn dot(a:Point,b:Point)->f64{a[0]*b[0]+a[1]*b[1]+a[2]*b[2]}
fn cross(a:Point,b:Point)->Point{[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]]}
fn length(p:Point)->f64{p[0].hypot(p[1]).hypot(p[2])}
fn distance(a:Point,b:Point)->f64{length(sub(a,b))}
fn edge_key(a:u32,b:u32)->(u32,u32){if a<b{(a,b)}else{(b,a)}}
struct Control<'a>{work:usize,limits:SolidBooleanLimits,caller:&'a mut dyn FnMut()->Result<()>}
impl Control<'_>{fn step(&mut self,cost:usize)->Result<()>{self.work=self.work.checked_add(cost).ok_or("boolean-work-limit")?;if self.work>self.limits.work{return fail("work-limit");}(self.caller)()}fn tick(&mut self)->Result<()>{self.step(1)}fn check(&mut self,depth:usize,count:usize)->Result<()>{self.tick()?;if depth>self.limits.depth{return fail("depth-limit");}if count>self.limits.polygons{return fail("polygon-limit");}Ok(())}}
#[derive(Clone,Copy)]
struct Plane{normal:Point,w:f64}
#[derive(Clone)]
struct Polygon{vertices:Vec<Point>,plane:Plane}
fn polygon(vertices:Vec<Point>)->Result<Polygon>{let normal=cross(sub(vertices[1],vertices[0]),sub(vertices[2],vertices[0]));let size=length(normal);if size<=EPS*EPS||!size.is_finite(){return fail("degenerate-triangle");}let normal=mul(normal,1./size);Ok(Polygon{plane:Plane{normal,w:dot(normal,vertices[0])},vertices})}
enum Split{Coplanar(Polygon,bool),Front(Polygon),Back(Polygon),Both(Option<Polygon>,Option<Polygon>)}
fn split(plane:Plane,p:Polygon,control:&mut Control<'_>)->Result<Split>{let mut kind=0;let mut types=Vec::new();for &v in &p.vertices{control.tick()?;let t=dot(plane.normal,v)-plane.w;let side=if t< -EPS{2}else if t>EPS{1}else{0};kind|=side;types.push(side);}match kind{0=>{let same=dot(plane.normal,p.plane.normal)>0.;return Ok(Split::Coplanar(p,same));},1=>return Ok(Split::Front(p)),2=>return Ok(Split::Back(p)),_=>()}
 let(mut front,mut back)=(Vec::new(),Vec::new());for i in 0..p.vertices.len(){control.tick()?;let j=(i+1)%p.vertices.len();let(vi,vj,ti,tj)=(p.vertices[i],p.vertices[j],types[i],types[j]);if ti!=2{front.push(vi);}if ti!=1{back.push(vi);}if (ti|tj)==3{let d=sub(vj,vi);let t=(plane.w-dot(plane.normal,vi))/dot(plane.normal,d);if !t.is_finite()||t< -EPS||t>1.+EPS{return fail("ill-conditioned-intersection");}let v=add(vi,mul(d,t.clamp(0.,1.)));front.push(v);back.push(v);}}
 fn clean(vertices:Vec<Point>,plane:Plane,c:&mut Control<'_>)->Result<Option<Polygon>>{let mut out=Vec::new();for v in vertices{c.tick()?;if out.last().is_none_or(|last|distance(v,*last)>EPS){out.push(v);}}if out.len()>1&&distance(out[0],out[out.len()-1])<=EPS{out.pop();}Ok((out.len()>=3).then_some(Polygon{vertices:out,plane}))}
 Ok(Split::Both(clean(front,p.plane,control)?,clean(back,p.plane,control)?))}
#[derive(Default)]
struct Node{plane:Option<Plane>,polygons:Vec<Polygon>,front:Option<Box<Node>>,back:Option<Box<Node>>}
impl Node{
 fn build(&mut self,polygons:Vec<Polygon>,c:&mut Control<'_>,depth:usize)->Result<()>{c.check(depth,polygons.len())?;if polygons.is_empty(){return Ok(());}let plane=*self.plane.get_or_insert(polygons[0].plane);let(mut f,mut b)=(Vec::new(),Vec::new());for p in polygons{c.tick()?;match split(plane,p,c)?{Split::Coplanar(p,_)=>self.polygons.push(p),Split::Front(p)=>f.push(p),Split::Back(p)=>b.push(p),Split::Both(front,back)=>{f.extend(front);b.extend(back);}}}c.check(depth,self.polygons.len())?;if !f.is_empty(){self.front.get_or_insert_with(Default::default).build(f,c,depth+1)?;}if !b.is_empty(){self.back.get_or_insert_with(Default::default).build(b,c,depth+1)?;}Ok(())}
 fn invert(&mut self,c:&mut Control<'_>,depth:usize)->Result<()>{c.check(depth,0)?;for p in &mut self.polygons{for _ in &p.vertices{c.tick()?;}p.vertices.reverse();p.plane=Plane{normal:mul(p.plane.normal,-1.),w:-p.plane.w};}if let Some(p)=&mut self.plane{p.normal=mul(p.normal,-1.);p.w= -p.w;}if let Some(node)=&mut self.front{node.invert(c,depth+1)?;}if let Some(node)=&mut self.back{node.invert(c,depth+1)?;}std::mem::swap(&mut self.front,&mut self.back);Ok(())}
 fn clip_polygons(&self,polygons:Vec<Polygon>,c:&mut Control<'_>,depth:usize)->Result<Vec<Polygon>>{c.check(depth,polygons.len())?;let Some(plane)=self.plane else{return Ok(polygons);};let(mut f,mut b)=(Vec::new(),Vec::new());for p in polygons{c.tick()?;match split(plane,p,c)?{Split::Coplanar(p,true)|Split::Front(p)=>f.push(p),Split::Coplanar(p,false)|Split::Back(p)=>b.push(p),Split::Both(front,back)=>{f.extend(front);b.extend(back);}}}if let Some(node)=&self.front{f=node.clip_polygons(f,c,depth+1)?;}if let Some(node)=&self.back{b=node.clip_polygons(b,c,depth+1)?;}else{b.clear();}f.extend(b);Ok(f)}
 fn clip_to(&mut self,other:&Node,c:&mut Control<'_>,depth:usize)->Result<()>{c.check(depth,0)?;self.polygons=other.clip_polygons(std::mem::take(&mut self.polygons),c,0)?;if let Some(node)=&mut self.front{node.clip_to(other,c,depth+1)?;}if let Some(node)=&mut self.back{node.clip_to(other,c,depth+1)?;}Ok(())}
 fn all(&self,c:&mut Control<'_>,depth:usize)->Result<Vec<Polygon>>{c.check(depth,0)?;let mut result=Vec::new();for p in &self.polygons{let mut vertices=Vec::new();for &v in &p.vertices{c.tick()?;vertices.push(v);}result.push(Polygon{vertices,plane:p.plane});}if let Some(node)=&self.front{result.extend(node.all(c,depth+1)?);}if let Some(node)=&self.back{result.extend(node.all(c,depth+1)?);}Ok(result)}
}
#[derive(Default)]
struct Weld{vertices:Vec<Point>,cells:HashMap<[i64;3],Vec<u32>>}
impl Weld{fn add(&mut self,point:Point,c:&mut Control<'_>)->Result<u32>{c.tick()?;if !point.iter().all(|v|v.is_finite()){return fail("nonfinite-vertex");}let cell=point.map(|v|(v/EPS).floor() as i64);for x in -1..=1{for y in -1..=1{for z in -1..=1{if let Some(values)=self.cells.get(&[cell[0]+x,cell[1]+y,cell[2]+z]){for &index in values{c.tick()?;if distance(point,self.vertices[index as usize])<=EPS{return Ok(index);}}}}}}let index=u32::try_from(self.vertices.len()).map_err(|_|"boolean-index-overflow")?;self.vertices.push(point);self.cells.entry(cell).or_default().push(index);Ok(index)}}
struct VertexIndex{axes:[Vec<(f64,u32)>;3]}
impl VertexIndex{
 fn new(vertices:&[Point],c:&mut Control<'_>)->Result<Self>{fn sorted(mut rows:Vec<(f64,u32)>,c:&mut Control<'_>)->Result<Vec<(f64,u32)>>{let mut width=1;while width<rows.len(){let mut out=Vec::with_capacity(rows.len());let mut start=0;while start<rows.len(){let mid=(start+width).min(rows.len());let end=(mid+width).min(rows.len());let(mut a,mut b)=(start,mid);while a<mid||b<end{c.tick()?;if b==end||a<mid&&rows[a].0<=rows[b].0{out.push(rows[a]);a+=1;}else{out.push(rows[b]);b+=1;}}start=end;}rows=out;width=width.checked_mul(2).ok_or("boolean-index-overflow")?;}Ok(rows)}let mut axes:[Vec<(f64,u32)>;3]=Default::default();for axis in 0..3{let mut rows=Vec::new();for(index,p)in vertices.iter().enumerate(){c.tick()?;rows.push((p[axis],u32::try_from(index).map_err(|_|"boolean-index-overflow")?));}axes[axis]=sorted(rows,c)?;}Ok(Self{axes})}
 fn candidates(&self,vertices:&[Point],a:Point,b:Point,c:&mut Control<'_>)->Result<Vec<u32>>{fn find(rows:&[(f64,u32)],value:f64,upper:bool,c:&mut Control<'_>)->Result<usize>{let(mut low,mut high)=(0,rows.len());while low<high{c.tick()?;let mid=(low+high)/2;if if upper{rows[mid].0<=value}else{rows[mid].0<value}{low=mid+1;}else{high=mid;}}Ok(low)}let mut best:Option<(usize,usize,usize)>=None;for axis in 0..3{let rows=&self.axes[axis];let low=find(rows,a[axis].min(b[axis])-EPS,false,c)?;let high=find(rows,a[axis].max(b[axis])+EPS,true,c)?;if best.is_none_or(|(_,lo,hi)|high-low<hi-lo){best=Some((axis,low,high));}}let(axis,low,high)=best.unwrap();let mut result=Vec::new();for &(_,id)in &self.axes[axis][low..high]{c.tick()?;let p=vertices[id as usize];if(0..3).all(|axis|p[axis]>=a[axis].min(b[axis])-EPS&&p[axis]<=a[axis].max(b[axis])+EPS){result.push(id);}}Ok(result)}
}
fn bounds(mesh:&SolidMesh,c:&mut Control<'_>)->Result<Option<[Point;2]>>{let mut result=None;for &p in &mesh.vertices{c.tick()?;if !p.iter().all(|v|v.is_finite()){return fail("nonfinite-vertex");}match &mut result{None=>result=Some([p,p]),Some(b)=>for axis in 0..3{b[0][axis]=b[0][axis].min(p[axis]);b[1][axis]=b[1][axis].max(p[axis]);}}}Ok(result)}
fn normalized(mesh:&SolidMesh,origin:Point,extent:f64,c:&mut Control<'_>)->Result<SolidMesh>{let mut weld=Weld::default();let mut indices=Vec::new();for &p in &mesh.vertices{indices.push(weld.add(mul(sub(p,origin),1./extent),c)?);}let mut triangles=Vec::new();for row in &mesh.triangles{c.tick()?;let mut t=[0;3];for i in 0..3{t[i]=*indices.get(row[i] as usize).ok_or("boolean-invalid-triangle-index")?;}triangles.push(t);}Ok(SolidMesh{vertices:weld.vertices,triangles})}
fn volume(mesh:&SolidMesh,c:&mut Control<'_>)->Result<f64>{let mut value=0.;for ids in &mesh.triangles{c.tick()?;let[a,b,d]=ids.map(|i|mesh.vertices[i as usize]);value+=dot(a,cross(b,d))/6.;}Ok(value)}
fn on_segment(p:Point,a:Point,b:Point)->bool{let d=sub(b,a);let size=dot(d,d);if size<=EPS*EPS{return false;}let t=dot(sub(p,a),d)/size;t>EPS&&t<1.-EPS&&distance(p,add(a,mul(d,t)))<=EPS}

#[derive(Clone)]
struct TriangleRow{ids:[u32;3],points:[Point;3],normal:Point,low:Point,high:Point}
fn self_intersections(mesh:&SolidMesh,c:&mut Control<'_>)->Result<()>{let mut rows=Vec::new();for &ids in &mesh.triangles{c.tick()?;let points=ids.map(|i|mesh.vertices[i as usize]);let normal=polygon(points.to_vec())?.plane.normal;let mut low=[0.;3];let mut high=[0.;3];for axis in 0..3{low[axis]=points.iter().map(|p|p[axis]).fold(f64::INFINITY,f64::min);high[axis]=points.iter().map(|p|p[axis]).fold(f64::NEG_INFINITY,f64::max);}rows.push(TriangleRow{ids,points,normal,low,high});}let index=VertexIndex::new(&rows.iter().map(|r|r.low).collect::<Vec<_>>(),c)?;let order:Vec<usize>=index.axes[0].iter().map(|p|p.1 as usize).collect();
 fn within(p:Point,t:&[Point;3],normal:Point)->bool{(0..3).all(|i|dot(cross(sub(t[(i+1)%3],t[i]),sub(p,t[i])),normal)>=-EPS)}
 fn uv(p:Point,axis:usize)->[f64;2]{[p[(axis+1)%3],p[(axis+2)%3]]}
 fn side(a:[f64;2],b:[f64;2],p:[f64;2])->f64{(b[0]-a[0])*(p[1]-a[1])-(b[1]-a[1])*(p[0]-a[0])}
 fn inside(p:Point,t:&[Point;3],axis:usize)->bool{let q=uv(p,axis);let s=[0,1,2].map(|i|side(uv(t[i],axis),uv(t[(i+1)%3],axis),q));s.iter().all(|v|*v>EPS*EPS)||s.iter().all(|v|*v< -EPS*EPS)}
 fn intersect(a:&TriangleRow,b:&TriangleRow,common:&[u32],mesh:&SolidMesh,c:&mut Control<'_>)->Result<()>{for edge in 0..3{c.tick()?;let(p,q)=(a.points[edge],a.points[(edge+1)%3]);let dp=dot(b.normal,sub(p,b.points[0]));let dq=dot(b.normal,sub(q,b.points[0]));if dp.abs()<=EPS&&dq.abs()<=EPS||dp>EPS&&dq>EPS||dp< -EPS&&dq< -EPS{continue;}let denominator=dp-dq;if denominator.abs()<=EPS*EPS{continue;}let value=dp/denominator;if value< -EPS||value>1.+EPS{continue;}let hit=add(p,mul(sub(q,p),value));if !within(hit,&b.points,b.normal){continue;}if common.iter().any(|id|distance(hit,mesh.vertices[*id as usize])<=4.*EPS){continue;}if common.len()==2&&on_segment(hit,mesh.vertices[common[0] as usize],mesh.vertices[common[1] as usize]){continue;}return fail("self-intersecting-solid");}Ok(())}
 for i in 0..order.len(){let a=&rows[order[i]];for &j in &order[i+1..]{c.tick()?;let b=&rows[j];if b.low[0]>a.high[0]+EPS{break;}if(1..3).any(|axis|a.high[axis]<b.low[axis]-EPS||b.high[axis]<a.low[axis]-EPS){continue;}let common:Vec<u32>=a.ids.iter().copied().filter(|id|b.ids.contains(id)).collect();let ad=b.points.map(|p|dot(a.normal,sub(p,a.points[0])));let bd=a.points.map(|p|dot(b.normal,sub(p,b.points[0])));if ad.iter().all(|v|*v>EPS)||ad.iter().all(|v|*v< -EPS)||bd.iter().all(|v|*v>EPS)||bd.iter().all(|v|*v< -EPS){continue;}if ad.iter().all(|v|v.abs()<=EPS)&&bd.iter().all(|v|v.abs()<=EPS){let mut axis=0;for k in 1..3{if a.normal[k].abs()>a.normal[axis].abs(){axis=k;}}let ca=mul(add(add(a.points[0],a.points[1]),a.points[2]),1./3.);let cb=mul(add(add(b.points[0],b.points[1]),b.points[2]),1./3.);if a.points.iter().any(|p|inside(*p,&b.points,axis))||b.points.iter().any(|p|inside(*p,&a.points,axis))||inside(ca,&b.points,axis)||inside(cb,&a.points,axis){return fail("self-intersecting-solid");}for x in 0..3{for y in 0..3{c.tick()?;let(p,q,r,s)=(uv(a.points[x],axis),uv(a.points[(x+1)%3],axis),uv(b.points[y],axis),uv(b.points[(y+1)%3],axis));let(u,v,w,z)=(side(p,q,r),side(p,q,s),side(r,s,p),side(r,s,q));if(u>EPS*EPS&&v< -EPS*EPS||u< -EPS*EPS&&v>EPS*EPS)&&(w>EPS*EPS&&z< -EPS*EPS||w< -EPS*EPS&&z>EPS*EPS){return fail("self-intersecting-solid");}}}}else{intersect(a,b,&common,mesh,c)?;intersect(b,a,&common,mesh,c)?;}}}Ok(())}
#[derive(Default)]
struct Edge{count:usize,direction:i32,owners:Vec<usize>}
fn shell_winding(mesh:&SolidMesh,edges:&BTreeMap<(u32,u32),Edge>,c:&mut Control<'_>)->Result<()>{let mut adjacency=vec![Vec::new();mesh.triangles.len()];for edge in edges.values(){c.tick()?;adjacency[edge.owners[0]].push(edge.owners[1]);adjacency[edge.owners[1]].push(edge.owners[0]);}let mut seen=HashSet::new();let mut components=Vec::new();for i in 0..mesh.triangles.len(){c.tick()?;if seen.contains(&i){continue;}let mut todo=vec![i];let mut component=Vec::new();while let Some(id)=todo.pop(){c.tick()?;if !seen.insert(id){continue;}component.push(id);for &n in &adjacency[id]{if !seen.contains(&n){todo.push(n);}}}components.push(component);}
 fn inside(point:Point,component:&[usize],mesh:&SolidMesh,c:&mut Control<'_>)->Result<bool>{let mut angle=0.;for &id in component{c.tick()?;let mut vectors=[[0.;3];3];for(i,&vertex)in mesh.triangles[id].iter().enumerate(){let v=sub(mesh.vertices[vertex as usize],point);let size=length(v);if size<=EPS{return fail("ambiguous-shell-nesting");}vectors[i]=mul(v,1./size);}let[a,b,d]=vectors;angle+=2.*dot(a,cross(b,d)).atan2(1.+dot(a,b)+dot(b,d)+dot(d,a));}let absolute=angle.abs();if absolute.min((absolute-4.*std::f64::consts::PI).abs())>1e-5{return fail("ambiguous-shell-nesting");}Ok(absolute>2.*std::f64::consts::PI)}
 for(i,component)in components.iter().enumerate(){let point=mesh.vertices[mesh.triangles[component[0]][0] as usize];let mut depth=0;for(j,other)in components.iter().enumerate(){if i!=j&&inside(point,other,mesh,c)?{depth+=1;}}let mut value=0.;for &id in component{c.tick()?;let[a,b,d]=mesh.triangles[id].map(|i|mesh.vertices[i as usize]);value+=dot(a,cross(b,d))/6.;}if value.abs()<=EPS*EPS*EPS||value.signum()!=if depth%2==0{1.}else{-1.}{return fail("invalid-shell-winding");}}Ok(())}
fn validate(mesh:&SolidMesh,c:&mut Control<'_>)->Result<()>{if mesh.triangles.is_empty(){return Ok(());}let mut edges:BTreeMap<(u32,u32),Edge>=BTreeMap::new();let mut links:BTreeMap<u32,BTreeMap<u32,Vec<u32>>>=BTreeMap::new();for(triangle,ids)in mesh.triangles.iter().enumerate(){c.tick()?;if ids[0]==ids[1]||ids[1]==ids[2]||ids[0]==ids[2]{return fail("degenerate-triangle");}polygon(ids.map(|i|mesh.vertices[i as usize]).to_vec())?;for i in 0..3{let(a,b)=(ids[i],ids[(i+1)%3]);let edge=edges.entry(edge_key(a,b)).or_default();edge.count+=1;edge.direction+=if a<b{1}else{-1};edge.owners.push(triangle);let link=links.entry(a).or_default();let(u,v)=(ids[(i+1)%3],ids[(i+2)%3]);link.entry(u).or_default().push(v);link.entry(v).or_default().push(u);}}
 for edge in edges.values(){c.tick()?;if edge.count!=2||edge.direction!=0{return fail("operand-not-closed-manifold");}}
 for link in links.values(){c.tick()?;if link.values().any(|v|v.len()!=2){return fail("nonmanifold-vertex-link");}let mut todo=vec![*link.keys().next().unwrap()];let mut seen=BTreeSet::new();while let Some(id)=todo.pop(){c.tick()?;if !seen.insert(id){continue;}for &n in &link[&id]{if !seen.contains(&n){todo.push(n);}}}if seen.len()!=link.len(){return fail("nonmanifold-vertex-link");}}
 let index=VertexIndex::new(&mesh.vertices,c)?;for &(a,b)in edges.keys(){for i in index.candidates(&mesh.vertices,mesh.vertices[a as usize],mesh.vertices[b as usize],c)?{c.tick()?;if i!=a&&i!=b&&on_segment(mesh.vertices[i as usize],mesh.vertices[a as usize],mesh.vertices[b as usize]){return fail("nonconforming-edge-vertex");}}}
 self_intersections(mesh,c)?;shell_winding(mesh,&edges,c)?;if volume(mesh,c)?<=EPS*EPS*EPS{return fail("invalid-solid-winding-or-volume");}Ok(())}
fn admit(mesh:&SolidMesh,c:&mut Control<'_>)->Result<()>{c.check(0,mesh.triangles.len())?;if mesh.triangles.is_empty(){bounds(mesh,c)?;return Ok(());}let b=bounds(mesh,c)?.ok_or("boolean-missing-vertices")?;let extent=sub(b[1],b[0]).into_iter().fold(0.,f64::max);if extent<=0.||!extent.is_finite(){return fail("coordinate-range");}validate(&normalized(mesh,b[0],extent,c)?,c)}
fn output(polygons:Vec<Polygon>,c:&mut Control<'_>)->Result<SolidMesh>{let mut weld=Weld::default();let mut rings=Vec::new();let mut planes=Vec::new();for p in polygons{c.tick()?;let mut indices=Vec::new();for v in p.vertices{let id=weld.add(v,c)?;if indices.last()!=Some(&id){indices.push(id);}}if indices.len()>1&&indices.first()==indices.last(){indices.pop();}if indices.len()>=3{rings.push(indices);planes.push(p.plane);}}
 let index=VertexIndex::new(&weld.vertices,c)?;let mut triangles=Vec::new();for(r,source)in rings.iter().enumerate(){c.tick()?;let mut ring=Vec::new();for i in 0..source.len(){let(a,b)=(source[i],source[(i+1)%source.len()]);let(u,v)=(weld.vertices[a as usize],weld.vertices[b as usize]);let d=sub(v,u);let size=dot(d,d);let mut inside:Vec<(u32,f64)>=Vec::new();ring.push(a);for id in index.candidates(&weld.vertices,u,v,c)?{c.tick()?;if id==a||id==b{continue;}let p=weld.vertices[id as usize];let t=dot(sub(p,u),d)/size;if t>EPS&&t<1.-EPS&&distance(p,add(u,mul(d,t)))<=EPS{let mut at=inside.len();while at>0{c.tick()?;if inside[at-1].1<=t{break;}at-=1;}inside.insert(at,(id,t));}}ring.extend(inside.into_iter().map(|p|p.0));}
 let mut guard=0;while ring.len()>3{c.tick()?;let mut found=false;for i in 0..ring.len(){c.tick()?;let(ia,ib,ic)=(ring[(i+ring.len()-1)%ring.len()],ring[i],ring[(i+1)%ring.len()]);let(a,b,d)=(weld.vertices[ia as usize],weld.vertices[ib as usize],weld.vertices[ic as usize]);let normal=planes[r].normal;if dot(cross(sub(b,a),sub(d,b)),normal)<=EPS*distance(a,b).max(distance(b,d)).max(distance(a,d)){continue;}let mut blocked=false;for &id in &ring{c.tick()?;if id==ia||id==ib||id==ic{continue;}let p=weld.vertices[id as usize];if dot(cross(sub(b,a),sub(p,a)),normal)>=-EPS*EPS&&dot(cross(sub(d,b),sub(p,b)),normal)>=-EPS*EPS&&dot(cross(sub(a,d),sub(p,d)),normal)>=-EPS*EPS{blocked=true;break;}}if blocked{continue;}triangles.push([ia,ib,ic]);c.check(0,triangles.len())?;ring.remove(i);found=true;break;}if !found{let mut area=0.;let mut perimeter=0.;let origin=weld.vertices[ring[0] as usize];for i in 0..ring.len(){c.tick()?;let a=weld.vertices[ring[i] as usize];let b=weld.vertices[ring[(i+1)%ring.len()] as usize];area+=dot(cross(sub(a,origin),sub(b,origin)),planes[r].normal);perimeter+=distance(a,b);}if area.abs()<=EPS*perimeter{ring.clear();break;}return fail("conforming-triangulation-failed");}guard+=1;if guard>source.len()+weld.vertices.len(){return fail("conforming-triangulation-failed");}}
 if ring.len()==3{let[a,b,d]=[ring[0],ring[1],ring[2]].map(|i|weld.vertices[i as usize]);let u=sub(b,a);let v=sub(d,a);if length(cross(u,v))>EPS*length(u).max(length(v)){triangles.push([ring[0],ring[1],ring[2]]);c.check(0,triangles.len())?;}}}
 let mut cursor=0;while cursor<triangles.len(){c.tick()?;let triangle=triangles[cursor];let mut split=false;for edge in 0..3{if split{break;}let(a,b,d)=(triangle[edge],triangle[(edge+1)%3],triangle[(edge+2)%3]);for id in index.candidates(&weld.vertices,weld.vertices[a as usize],weld.vertices[b as usize],c)?{c.tick()?;if id==a||id==b||id==d||!on_segment(weld.vertices[id as usize],weld.vertices[a as usize],weld.vertices[b as usize]){continue;}triangles[cursor]=[a,id,d];triangles.push([id,b,d]);c.check(0,triangles.len())?;split=true;break;}}if !split{cursor+=1;}}
 let mut remap=HashMap::new();let mut vertices=Vec::new();for triangle in &mut triangles{for id in triangle{c.tick()?;let next=if let Some(&next)=remap.get(id){next}else{let next=u32::try_from(vertices.len()).map_err(|_|"boolean-index-overflow")?;vertices.push(weld.vertices[*id as usize]);remap.insert(*id,next);next};*id=next;}}let mesh=SolidMesh{vertices,triangles};validate(&mesh,c)?;Ok(mesh)}
fn copy_mesh(mesh:&SolidMesh,c:&mut Control<'_>)->Result<SolidMesh>{c.check(0,mesh.triangles.len())?;let mut result=SolidMesh::default();for &v in &mesh.vertices{c.tick()?;result.vertices.push(v);}for &t in &mesh.triangles{c.tick()?;result.triangles.push(t);}c.step(0)?;Ok(result)}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum SolidBooleanOperation{Difference,Union,Intersection}
/// 🧊️ Apply a regularized Boolean operation to closed finite oriented solids with original caller control.
pub fn boolean_solid(operation:SolidBooleanOperation,left:&SolidMesh,right:&SolidMesh,limits:SolidBooleanLimits,tick:&mut dyn FnMut()->Result<()>)->Result<SolidMesh>{if limits.work==0||limits.polygons==0||limits.depth==0||[limits.work,limits.polygons,limits.depth].into_iter().any(|v|v as u64>9_007_199_254_740_991){return fail("invalid-limits");}let mut c=Control{work:0,limits,caller:tick};c.step(0)?;boolean_with_control(operation,left,right,&mut c)}
fn boolean_with_control(operation:SolidBooleanOperation,left:&SolidMesh,right:&SolidMesh,c:&mut Control<'_>)->Result<SolidMesh>{admit(left,c)?;admit(right,c)?;if left.triangles.is_empty(){if operation==SolidBooleanOperation::Union{return copy_mesh(right,c);}c.step(0)?;return Ok(SolidMesh::default());}if right.triangles.is_empty(){if operation!=SolidBooleanOperation::Intersection{return copy_mesh(left,c);}c.step(0)?;return Ok(SolidMesh::default());}let ab=bounds(left,c)?.unwrap();let bb=bounds(right,c)?.unwrap();if operation!=SolidBooleanOperation::Union&&(0..3).any(|i|ab[1][i]<=bb[0][i]||bb[1][i]<=ab[0][i]){if operation==SolidBooleanOperation::Difference{return copy_mesh(left,c);}c.step(0)?;return Ok(SolidMesh::default());}let low=[0,1,2].map(|i|ab[0][i].min(bb[0][i]));let high=[0,1,2].map(|i|ab[1][i].max(bb[1][i]));let origin=[0,1,2].map(|i|low[i]/2.+high[i]/2.);let extent=sub(high,low).into_iter().fold(0.,f64::max);if extent<=0.||!extent.is_finite(){return fail("coordinate-range");}let am=normalized(left,origin,extent,c)?;let bm=normalized(right,origin,extent,c)?;fn polygons(mesh:&SolidMesh,c:&mut Control<'_>)->Result<Vec<Polygon>>{let mut out=Vec::new();for ids in &mesh.triangles{c.tick()?;out.push(polygon(ids.map(|i|mesh.vertices[i as usize]).to_vec())?);}Ok(out)}let mut a=Node::default();let mut b=Node::default();a.build(polygons(&am,c)?,c,0)?;b.build(polygons(&bm,c)?,c,0)?;match operation{SolidBooleanOperation::Difference=>{a.invert(c,0)?;a.clip_to(&b,c,0)?;b.clip_to(&a,c,0)?;b.invert(c,0)?;b.clip_to(&a,c,0)?;b.invert(c,0)?;a.build(b.all(c,0)?,c,0)?;a.invert(c,0)?;},SolidBooleanOperation::Union=>{a.clip_to(&b,c,0)?;b.clip_to(&a,c,0)?;b.invert(c,0)?;b.clip_to(&a,c,0)?;b.invert(c,0)?;a.build(b.all(c,0)?,c,0)?;},SolidBooleanOperation::Intersection=>{a.invert(c,0)?;b.clip_to(&a,c,0)?;b.invert(c,0)?;a.clip_to(&b,c,0)?;b.clip_to(&a,c,0)?;a.build(b.all(c,0)?,c,0)?;a.invert(c,0)?;}}let mut result=output(a.all(c,0)?,c)?;for p in &mut result.vertices{c.tick()?;*p=add(origin,mul(*p,extent));if !p.iter().all(|v|v.is_finite()){return fail("nonfinite-output-vertex");}}c.step(0)?;Ok(result)}
/// 🧊️ Subtract closed solids under the same regularized Boolean contract.
pub fn subtract_solid(left:&SolidMesh,right:&SolidMesh,limits:SolidBooleanLimits,tick:&mut dyn FnMut()->Result<()>)->Result<SolidMesh>{boolean_solid(SolidBooleanOperation::Difference,left,right,limits,tick)}

/// ✂️ A plane whose positive signed side is removed from the admitted source solid.
#[derive(Clone,Copy,Debug,PartialEq)]
pub struct SolidPlane{pub origin:SolidPoint,pub normal:SolidPoint}
/// ✂️ Restrict a plane halfspace exactly to the finite host domain under original caller control.
pub fn subtract_half_space(left:&SolidMesh,plane:&SolidPlane,limits:SolidBooleanLimits,tick:&mut dyn FnMut()->Result<()>)->Result<SolidMesh>{
 if limits.work==0||limits.polygons==0||limits.depth==0||[limits.work,limits.polygons,limits.depth].into_iter().any(|v|v as u64>9_007_199_254_740_991){return fail("invalid-limits");}let mut c=Control{work:0,limits,caller:tick};c.step(0)?;admit(left,&mut c)?;if !plane.origin.iter().chain(&plane.normal).all(|v|v.is_finite()){return fail("invalid-halfspace-plane");}let largest=plane.normal.into_iter().map(f64::abs).fold(0.,f64::max);if largest<=0.{return fail("invalid-halfspace-normal");}let mut n=plane.normal.map(|v|v/largest);n=mul(n,1./length(n));if left.triangles.is_empty(){c.step(0)?;return Ok(SolidMesh::default());}let domain=bounds(left,&mut c)?.unwrap();let origin=domain[0];let extent=sub(domain[1],origin).into_iter().fold(0.,f64::max);let high=mul(sub(domain[1],origin),1./extent);let plane_origin=mul(sub(plane.origin,origin),1./extent);let w=dot(n,plane_origin);if !w.is_finite()||!plane_origin.iter().all(|v|v.is_finite()){return fail("halfspace-coordinate-range");}let[x,y,z]=high;let vertices=[[0.,0.,0.],[x,0.,0.],[x,y,0.],[0.,y,0.],[0.,0.,z],[x,0.,z],[x,y,z],[0.,y,z]];let mut distances=[0.;8];for(i,v)in vertices.iter().enumerate(){c.tick()?;distances[i]=dot(n,*v)-w;}if distances.into_iter().fold(f64::NEG_INFINITY,f64::max)<=0.{return copy_mesh(left,&mut c);}if distances.into_iter().fold(f64::INFINITY,f64::min)>=0.{c.step(0)?;return Ok(SolidMesh::default());}if distances.into_iter().any(|d|d!=0.&&d.abs()<=EPS){return fail("ambiguous-halfspace-domain-intersection");}
 let mut polygons=Vec::new();let mut cap=Weld::default();for face in [[0,3,2,1],[4,5,6,7],[0,1,5,4],[1,2,6,5],[2,3,7,6],[3,0,4,7]]{let source:Vec<Point>=face.map(|i|vertices[i]).to_vec();let mut clipped=Vec::new();for i in 0..4{c.tick()?;let j=(i+1)%4;let(a,b)=(source[i],source[j]);let(da,db)=(distances[face[i]],distances[face[j]]);let(inside,next_inside)=(da>=0.,db>=0.);if inside{clipped.push(a);if da==0.{cap.add(a,&mut c)?;}}if inside!=next_inside{let t=da/(da-db);if !t.is_finite()||t< -EPS||t>1.+EPS{return fail("ill-conditioned-halfspace-intersection");}let point=add(a,mul(sub(b,a),t.clamp(0.,1.)));clipped.push(point);cap.add(point,&mut c)?;}}let mut clean=Vec::new();for point in clipped{if clean.last().is_none_or(|last|distance(point,*last)>EPS){clean.push(point);}}if clean.len()>1&&distance(clean[0],*clean.last().unwrap())<=EPS{clean.pop();}if clean.len()>=3{polygons.push(Polygon{vertices:clean,plane:polygon(source)?.plane});}}
 if cap.vertices.len()<3{return fail("ambiguous-halfspace-cap");}let mut center=[0.;3];for &point in &cap.vertices{c.tick()?;center=add(center,mul(point,1./cap.vertices.len() as f64));}let outward=mul(n,-1.);let axis=if outward[0].abs()<=outward[1].abs()&&outward[0].abs()<=outward[2].abs(){[1.,0.,0.]}else if outward[1].abs()<=outward[2].abs(){[0.,1.,0.]}else{[0.,0.,1.]};let mut u=cross(outward,axis);u=mul(u,1./length(u));let v=cross(outward,u);let mut ordered:Vec<(Point,f64)>=Vec::new();for point in cap.vertices{c.tick()?;let d=sub(point,center);let angle=dot(d,v).atan2(dot(d,u));let mut at=ordered.len();while at>0{c.tick()?;if ordered[at-1].1<=angle{break;}at-=1;}ordered.insert(at,(point,angle));}let ring:Vec<Point>=ordered.into_iter().map(|p|p.0).collect();let w=dot(outward,ring[0]);polygons.push(Polygon{vertices:ring,plane:Plane{normal:outward,w}});let mut cutter=output(polygons,&mut c)?;for p in &mut cutter.vertices{c.tick()?;*p=add(origin,mul(*p,extent));if !p.iter().all(|v|v.is_finite()){return fail("nonfinite-output-vertex");}}boolean_with_control(SolidBooleanOperation::Difference,left,&cutter,&mut c)
}
